use serde::{Deserialize, Serialize};

/// Deterministic effect categories, never descriptions generated by a model.
#[derive(Clone, Copy, Debug, Default, Deserialize, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ApprovalAction {
    DeleteStore,
    DeleteRecords,
    DropObjects,
    DropColumns,
    ReplaceRecords,
    UpdateRecords,
    #[default]
    ChangeData,
}

/// Trusted host-side presentation metadata. It has no JSON/tool constructor.
/// Transport adapters render a card and authenticate the human interaction;
/// the executor remains responsible for checking and claiming the exact operation.
#[derive(Clone, Debug)]
pub struct ApprovalPresentation {
    pub executor: String,
    pub operation_id: String,
    pub operation_hash: String,
    pub recipient_principal: String,
    pub private_destination: String,
    pub expires_at: i64,
    pub action: ApprovalAction,
    pub resource: String,
    pub objects: Vec<String>,
    pub decision_kind: String,
    pub status_kind: String,
}
